5	import { SignOutButton } from "./sign-out-button";
6	
7	// Links follow the DB role (memberships / tenants.user_id), never user_metadata. If the lookup fails the
8	// header still renders, just without links.
9	async function navLinks(): Promise<NavLink[]> {
10	  try {
11	    const userId = await getUserId();
12	    if (!userId) return [];
13	    const caller = await loadCaller(userId);
14	    const links: NavLink[] = [];
15	    if (caller.member) {
16	      links.push({ href: "/dashboard", label: "Dashboard" }, { href: "/leases", label: "Leases" });
17	    }
18	    if (caller.tenantIds.length > 0) links.push({ href: "/tenant", label: "My tenancy" });
19	    return links;
20	  } catch {
21	    return [];
22	  }
23	}
24	
25	export async function AppHeader({ email }: { email: string }) {
26	  const links = await navLinks();
27	  return (
