92	export function LeaseSection({
93	  lease,
94	  invoices,
95	  payments,
96	  paidByInvoice,
97	  now,
98	}: {
99	  lease: LeaseView;
100	  invoices: InvoiceView[];
101	  payments: PaymentView[];
102	  paidByInvoice: Map<string, number>;
103	  // Client-only "now" (set after mount), so nothing time-dependent is rendered by the server (R52).
104	  now: Date;
105	}) {
106	  const [bill, setBill] = useState<CreatedBill | null>(null);
107	  const [creating, setCreating] = useState(false);
108	
109	  const rows = invoices.map((inv) => {
110	    const paidSen = paidByInvoice.get(inv.id) ?? 0;
111	    return { inv, paidSen, status: invoiceStatus({ dueDate: inv.dueDate, amountSen: inv.amountSen, paidSen }, now) };
112	  });
113	
114	  // R30 mirror: unpaid amounts of invoices due on or before today's Malaysia date. The server recomputes it.
115	  const today = toMytDate(now);
116	  const dueNowSen = rows.reduce(
117	    (sum, r) => (r.inv.dueDate <= today ? sum + Math.max(r.inv.amountSen - r.paidSen, 0) : sum),
118	    0,
119	  );
120	
121	  async function payNow() {
122	    setCreating(true);
123	    try {
124	      const res = await fetch(`/api/leases/${lease.id}/gateway-bills`, { method: "POST" });
125	      const body: unknown = await res.json().catch(() => null);
126	      if (res.status === 201 && isCreatedBill(body)) {
127	        setBill(body);
128	        toast.success("Payment bill created");
129	      } else if (res.status === 422) {
130	        toast.error("Nothing is due");
131	      } else {
132	        toast.error(errorMessage(body) ?? "Could not create the payment bill");
133	      }
134	    } catch {
135	      toast.error("Could not reach the server");
136	    } finally {
137	      setCreating(false);
138	    }
139	  }
140	
141	  return (
142	    <Card>
143	      <CardHeader>
144	        <CardTitle>Unit {lease.unitName}</CardTitle>
145	        <CardDescription>
146	          Lease {lease.startDate} to {lease.endDate} · Rent {formatSen(lease.monthlyRentSen)} per month · Deposit{" "}
147	          {formatSen(lease.depositSen)}
148	        </CardDescription>
149	      </CardHeader>
150	      <CardContent className="flex flex-col gap-6">
151	        <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-4">
152	          <div>
153	            <p className="text-sm text-muted-foreground">Amount due now</p>
154	            <p className="text-2xl font-semibold" data-testid="amount-due-now">
155	              {formatSen(dueNowSen)}
156	            </p>
157	            {dueNowSen === 0 && (
158	              <p className="text-sm text-muted-foreground">Nothing is due right now.</p>
159	            )}
160	          </div>
161	          <Button onClick={payNow} disabled={dueNowSen === 0 || creating}>
162	            {creating ? "Creating bill..." : "Pay now"}
163	          </Button>
164	        </div>
165	
166	        {bill && (
167	          <Card size="sm" className="border-primary/40">
168	            <CardHeader>
169	              <CardTitle>Payment bill created</CardTitle>
170	              <CardDescription>
171	                The bill is settled only when the gateway confirms it. Paying here does not change anything by itself.
172	              </CardDescription>
173	            </CardHeader>
174	            <CardContent className="flex flex-col gap-3 text-sm">
175	              <dl className="grid grid-cols-[max-content_1fr] gap-x-4 gap-y-1">
176	                <dt className="text-muted-foreground">Bill id</dt>
177	                <dd className="font-mono break-all" data-testid="bill-id">
178	                  {bill.billId}
179	                </dd>
180	                <dt className="text-muted-foreground">Amount</dt>
181	                <dd>{formatSen(bill.amountSen)}</dd>
182	              </dl>
183	              <div>
184	                <p className="mb-1 text-muted-foreground">Simulate the gateway callback:</p>
185	                <code className="block rounded-md bg-muted px-3 py-2 font-mono text-xs break-all select-all">
186	                  node gateway-sim.mjs {bill.billId} {bill.amountSen} true
187	                </code>
188	              </div>
189	              <Link
190	                href={`/payments/return?bill_id=${bill.billId}&paid=true`}
191	                className={cn(buttonVariants({ variant: "outline" }), "w-fit")}
192	              >
193	                Go to the return page
194	              </Link>
195	            </CardContent>
196	          </Card>
197	        )}
198	
199	        <section className="flex flex-col gap-2">
200	          <h3 className="text-sm font-semibold">Invoices</h3>
201	          {rows.length === 0 ? (
202	            <p className="text-sm text-muted-foreground">No invoices yet.</p>
203	          ) : (
204	            <Table>
205	              <TableHeader>
206	                <TableRow>
207	                  <TableHead>Invoice</TableHead>
208	                  <TableHead>Period</TableHead>
209	                  <TableHead>Due</TableHead>
210	                  <TableHead className="text-right">Amount</TableHead>
211	                  <TableHead className="text-right">Paid</TableHead>
212	                  <TableHead>Status</TableHead>
213	                </TableRow>
214	              </TableHeader>
215	              <TableBody>
216	                {rows.map(({ inv, paidSen, status }) => (
217	                  <TableRow key={inv.id}>
218	                    <TableCell>{describeInvoice(inv)}</TableCell>
219	                    <TableCell>
220	                      {inv.periodStart && inv.periodEnd ? `${inv.periodStart} to ${inv.periodEnd}` : "-"}
221	                    </TableCell>
222	                    <TableCell>{inv.dueDate}</TableCell>
223	                    <TableCell className="text-right">{formatSen(inv.amountSen)}</TableCell>
224	                    <TableCell className="text-right">{formatSen(paidSen)}</TableCell>
225	                    <TableCell>
226	                      <Badge variant={STATUS_BADGE[status]}>{STATUS_LABEL[status]}</Badge>
227	                    </TableCell>
228	                  </TableRow>
229	                ))}
230	              </TableBody>
231	            </Table>
232	          )}
233	        </section>
234	
235	        <section className="flex flex-col gap-2">
236	          <h3 className="text-sm font-semibold">Payments</h3>
237	          {payments.length === 0 ? (
238	            <p className="text-sm text-muted-foreground">No payments yet.</p>
239	          ) : (
240	            <Table>
241	              <TableHeader>
242	                <TableRow>
243	                  <TableHead>Received (Malaysia time)</TableHead>
244	                  <TableHead>Method</TableHead>
245	                  <TableHead className="text-right">Amount</TableHead>
246	                  <TableHead>Status</TableHead>
247	                </TableRow>
248	              </TableHeader>
249	              <TableBody>
250	                {payments.map((p) => (
251	                  <TableRow key={p.id}>
252	                    <TableCell>{formatMytDisplay(new Date(p.receivedAt))}</TableCell>
253	                    <TableCell>{METHOD_LABEL[p.method]}</TableCell>
254	                    <TableCell className="text-right">{formatSen(p.amountSen)}</TableCell>
255	                    <TableCell>
256	                      <Badge variant={p.status === "approved" ? "default" : p.status === "pending_verification" ? "secondary" : "outline"}>
257	                        {PAYMENT_STATUS_LABEL[p.status]}
258	                      </Badge>
259	                    </TableCell>
260	                  </TableRow>
261	                ))}
262	              </TableBody>
263	            </Table>
264	          )}
265	        </section>
266	      </CardContent>
267	    </Card>
268	  );
269	}
